with open('/app/dataset/genealogy_trees.txt', 'r', encoding='utf-8') as f:
    lines = [l.rstrip('\n') for l in f]

for char in ['/', '\\', '.', '=', '_', '1']:
    found = []
    for r, line in enumerate(lines):
        for c, ch in enumerate(line):
            if ch == char:
                found.append((r, c))
    print(f'{char}: {len(found)} times, e.g. {found[:5]}')
